                Xyz aXYZ = new Xyz(0.0, 0.0, 0.0);
                int nsub3 = 0;
                if (data.ReadSubList(nsub2, i, "coordinates", ach, ref nsub3))
                {
                    int nb3 = data.NbParams(nsub3);
                    if (nb3 > 3)
